mapper.select:
SELECT ss.id AS id, sku.id AS skuId, sku.sku_code AS skuCode, sku.pic AS pic, spu.id AS spuId, spu.name AS spuName, COALESCE(ss.stock, 0) AS stock, COALESCE(ss.lock_stock, 0) AS lockStock, COALESCE(ss.sale, 0) AS sale, COALESCE(ss.low_stock, 0) AS lowStock, COALESCE(ss.stock_status, 0) AS stockStatus, ss.version AS version, ss.create_time AS createTime, ss.update_time AS updateTime, CASE WHEN COALESCE(ss.low_stock, 0) > 0 AND COALESCE(ss.stock, 0) <= COALESCE(ss.low_stock, 0) THEN TRUE ELSE FALSE END AS lowStockWarning FROM product_sku sku INNER JOIN product_spu spu ON spu.id = sku.spu_id AND spu.deleted = 0 LEFT JOIN product_sku_stock ss ON ss.sku_id = sku.id
AND sku.deleted = 0
AND (spu.name LIKE CONCAT('%', #{reqVO.keyword,jdbcType=VARCHAR}, '%') OR sku.sku_code LIKE CONCAT('%', #{reqVO.keyword,jdbcType=VARCHAR}, '%'))
AND spu.id = #{reqVO.spuId,jdbcType=BIGINT}
AND sku.id = #{reqVO.skuId,jdbcType=BIGINT}
AND spu.brand_id = #{reqVO.brandId,jdbcType=BIGINT}
AND spu.category_id = #{reqVO.categoryId,jdbcType=BIGINT}
AND COALESCE(ss.stock_status, 0) = #{reqVO.stockStatus,jdbcType=TINYINT}
AND COALESCE(ss.low_stock, 0) > 0 AND COALESCE(ss.stock, 0) <= COALESCE(ss.low_stock, 0)
AND COALESCE(ss.stock, 0) <= 0
AND COALESCE(ss.stock_status, 0) = 2
ORDER BY COALESCE(ss.update_time, sku.update_time) DESC, sku.id DESC

